// Embeds drizzle/ (generated by drizzle-kit) into src/state/migrations.gen.ts, so migrations
// ship inside the single-file executable. Run via `bun run db:generate`.
import { join } from "node:path";
import { $ } from "bun";

const root = join(import.meta.dir, "..");
const journal = (await Bun.file(join(root, "drizzle/meta/_journal.json")).json()) as {
  entries: { tag: string }[];
};
const out = join(root, "src/state/migrations.gen.ts");

const imports = journal.entries.map(
  ({ tag }, i) => `import m${i} from "../../drizzle/${tag}.sql" with { type: "text" };`,
);
const files = journal.entries.map(({ tag }, i) => `  ${JSON.stringify(tag)}: m${i},`);

await Bun.write(
  out,
  `// Generated by scripts/embed-migrations.ts from drizzle/. Do not edit.
import journal from "../../drizzle/meta/_journal.json";
${imports.join("\n")}

export { journal };

/** Migration SQL by journal tag. */
export const migrationFiles: Record<string, string> = {
${files.join("\n")}
};
`,
);
await $`bunx biome check --write ${out}`.quiet();
console.log(`Embedded ${journal.entries.length} migration(s) into ${out}`);
